import{_ as o,o as t,c as a,a3 as i}from"./chunks/framework.BTQ4eCVb.js";const m=JSON.parse('{"title":"Reseller Payouts — Production Guide","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Reseller Payouts — Production Guide | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/deployment/reseller-payouts"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Reseller Payouts — Production Guide | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/deployment/reseller-payouts"}]]},"headers":[],"relativePath":"deployment/reseller-payouts.md","filePath":"deployment/reseller-payouts.md","lastUpdated":1788644779000}'),r={name:"deployment/reseller-payouts.md"};function s(n,e,d,l,c,p){return t(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="reseller-payouts-—-production-guide" tabindex="-1">Reseller Payouts — Production Guide <a class="header-anchor" href="#reseller-payouts-—-production-guide" aria-label="Permalink to &quot;Reseller Payouts — Production Guide&quot;">​</a></h1><h2 id="licensing" tabindex="-1">Licensing <a class="header-anchor" href="#licensing" aria-label="Permalink to &quot;Licensing&quot;">​</a></h2><ul><li>Catalog slug: <code>reseller-payouts</code></li><li>Category: <code>sales</code> (<strong>Sales</strong>), <code>category_sort_order = 20</code>, module <code>sort_order = 80</code></li><li><strong>Free Marketplace opt-in</strong> (<code>is_default_included = false</code>, <code>is_billable = false</code>, price <code>0</code>)</li><li>Hard dependency: <strong>Resellers</strong> (which itself requires <strong>Payments</strong>)</li><li>Marketplace blocks install until Resellers is entitled</li></ul><h2 id="bootstrap" tabindex="-1">Bootstrap <a class="header-anchor" href="#bootstrap" aria-label="Permalink to &quot;Bootstrap&quot;">​</a></h2><ol><li>Ensure Resellers (and Payments) are entitled first</li><li>Enable Reseller Payouts from Marketplace</li><li>Permissions via <code>2026_08_06_100007_add_reseller_payouts_permissions</code></li></ol><p>Without Reseller Payouts entitlement, invoice Paid transitions do <strong>not</strong> create commission rows (listeners no-op after entitlement check).</p><h2 id="schema-migrations" tabindex="-1">Schema migrations <a class="header-anchor" href="#schema-migrations" aria-label="Permalink to &quot;Schema migrations&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Migration</th><th>Purpose</th></tr></thead><tbody><tr><td><code>2026_08_06_100002_create_reseller_commission_entries_table</code></td><td>ledger + unique <code>(customer_invoice_id, party)</code></td></tr><tr><td><code>2026_08_06_100006_register_reseller_payouts_module</code></td><td>catalog via <code>DefaultModuleRegistrar</code></td></tr><tr><td><code>2026_08_06_100008_add_reseller_payouts_resellers_dependency</code></td><td>hard dep → resellers</td></tr></tbody></table><h2 id="event-wiring" tabindex="-1">Event wiring <a class="header-anchor" href="#event-wiring" aria-label="Permalink to &quot;Event wiring&quot;">​</a></h2><p><code>AppServiceProvider</code>:</p><ul><li><code>CustomerInvoiceBecamePaid</code> → <code>AccrueResellerCommission</code></li><li><code>CustomerInvoiceLeftPaid</code> → <code>VoidResellerCommission</code></li></ul><p>Transitions are dispatched from <code>CustomerInvoicePaidTransitions</code> after invoice status recalculation (Payments post/void paths included).</p><h2 id="monitoring" tabindex="-1">Monitoring <a class="header-anchor" href="#monitoring" aria-label="Permalink to &quot;Monitoring&quot;">​</a></h2><ul><li>Spatie activity log name: <code>reseller_commission_entries</code></li><li>Track accrue/approve/pay/void volume via application logs / Nightwatch as needed</li></ul><h2 id="deploy-checklist" tabindex="-1">Deploy checklist <a class="header-anchor" href="#deploy-checklist" aria-label="Permalink to &quot;Deploy checklist&quot;">​</a></h2><ol><li>Migrate commission table + catalog + permissions + Resellers dependency</li><li>Confirm <code>module:reseller-payouts</code> + <code>reseller-payouts.*</code> on admin/manager/staff/reseller maps</li><li>Confirm listeners registered in deployed app container</li><li>Smoke: Paid invoice with <code>reseller_id</code> → two accrued rows → approve → pay; void invoice payment → entries voided; re-post payment → entries revived to accrued</li><li>Confirm Partial invoices do <strong>not</strong> accrue</li></ol><h2 id="finance-runbook-—-invoice-leaves-paid" tabindex="-1">Finance runbook — invoice leaves Paid <a class="header-anchor" href="#finance-runbook-—-invoice-leaves-paid" aria-label="Permalink to &quot;Finance runbook — invoice leaves Paid&quot;">​</a></h2><p>Leaving Paid (<code>CustomerInvoiceLeftPaid</code>, typically from <strong>voiding a posted payment</strong>) calls <code>voidForInvoice</code>, which bulk-voids <strong>every</strong> non-void commission row for that invoice — <strong>including entries already marked <code>paid</code></strong>.</p><p>This is intentional Phase 1 behavior so the ledger cannot stay “settled” against an unpaid invoice:</p><table tabindex="0"><thead><tr><th>Situation</th><th>Result</th></tr></thead><tbody><tr><td>Accrued / approved entry, invoice unpays</td><td>Status → <code>void</code></td></tr><tr><td>Manually marked <code>paid</code> entry, invoice unpays</td><td>Status → <code>void</code> (finance must treat as cancelled settlement)</td></tr><tr><td>Invoice becomes Paid again</td><td>Void rows for that invoice are <strong>revived</strong> to <code>accrued</code> with refreshed amount snapshots</td></tr></tbody></table><p><strong>Ops guidance:</strong> If commissions were already disbursed outside the app before a payment void, reverse or reclaim that disbursement in your payroll/AP process — EloSync marks the ledger void but does not move money. Manual <strong>Void</strong> on a single entry still rejects rows that are already <code>paid</code> while the invoice remains Paid.</p><h2 id="deferred" tabindex="-1">Deferred <a class="header-anchor" href="#deferred" aria-label="Permalink to &quot;Deferred&quot;">​</a></h2><p>No automated disbursement gateway in Phase 1 — <code>pay</code> is ledger status only. Cross-workspace identity for parties remains deferred.</p>',23)])])}const h=o(r,[["render",s]]);export{m as __pageData,h as default};
